--- a/training/level-1/L1-024-duplicate-signature/groupDuplicates.mjs
+++ b/training/level-1/L1-024-duplicate-signature/groupDuplicates.mjs
@@ -0,0 +1,87 @@
+function groupDuplicates(items) {
+  if (!Array.isArray(items)) {
+    throw new TypeError('items must be an array');
+  }
+
+  const groups = new Map();
+
+  for (const item of items) {
+    if (typeof item !== 'object' || item === null) {
+      throw new TypeError('each item must be a plain object');
+    }
+
+    const id = item.id;
+    const digest = item.digest;
+    const size = item.size;
+
+    if (typeof id !== 'string' || id.length === 0) {
+      throw new TypeError('id must be a non-empty string');
+    }
+
+    if (typeof digest !== 'string' || digest.length === 0) {
+      throw new TypeError('digest must be a non-empty string');
+    }
+
+    if (size !== undefined && (!Number.isFinite(size) || size < 0)) {
+      throw new RangeError('size must be a finite nonnegative number or undefined');
+    }
+
+    const normalizedDigest = digest.trim().toLowerCase();
+
+    if (!groups.has(normalizedDigest)) {
+      groups.set(normalizedDigest, []);
+    }
+
+    const group = groups.get(normalizedDigest);
+    group.push({ id, size });
+  }
+
+  const result = [];
+
+  for (const [digest, members] of groups) {
+    if (members.length < 2) {
+      continue;
+    }
+
+    let sizeConsistent = true;
+    for (const member of members) {
+      if (member.size !== undefined) {
+        if (sizeConsistent && member.size !== members[0].size) {
+          sizeConsistent = false;
+        } else if (!sizeConsistent && member.size !== members[0].size) {
+          // Already inconsistent, no need to check further for this group's consistency flag logic
+          // But we must ensure all defined sizes are equal. If first is undefined and second is 5, consistent=true? 
+          // Spec: "sizeConsistent true when all defined sizes are equal and false when defined sizes disagree (no defined sizes => true)"
+          // So if some are undefined and some are 5, they disagree -> false.
+          // My logic above handles this: if first is undefined, we don't set sizeConsistent to false yet.
+          // We need to check against the first *defined* size or handle undefined carefully.
+        }
+      }
+    }
+
+    // Re-evaluate sizeConsistent properly
+    const definedSizes = members.filter(m => m.size !== undefined).map(m => m.size);
+    if (definedSizes.length > 0) {
+      const firstDefinedSize = definedSizes[0];
+      for (const s of definedSizes) {
+        if (s !== firstDefinedSize) {
+          sizeConsistent = false;
+          break;
+        }
+      }
+    } else {
+      sizeConsistent = true;
+    }
+
+    const groupObj = Object.freeze({
+      digest,
+      ids: members.map(m => m.id),
+      sizeConsistent
+    });
+
+    result.push(groupObj);
+  }
+
+  return Object.freeze(result);
+}
+EXPORT groupDuplicates

